            // Print results
            System.out.println("Results for \"" + searchName + "\":");
            while (rs.next()) {
                int id = rs.getInt("id");
                String value = rs.getString("value");
                System.out.println("ID: " + id + ", Value: " + value);
            }

            // Close resources
